algorithms.pseudocode:
function ENTRY(m):
    if m == 1: return 1
    (a, b) <- (0, 1)            # (F(0) mod m, F(1) mod m)
    k <- 0
    loop:
        k <- k + 1
        (a, b) <- (b, (a + b) mod m)   # now (F(k) mod m, F(k+1) mod m)
        if a == 0:
            return k               # least positive index with m | F(k)

function FIB_DIVIDES_FIB(m, n):
    if m <= 2: return TRUE          # F(1)=F(2)=1 divides everything
    return (n mod m == 0)           # converse divisibility law

function FIB_VALUES_COPRIME(m, n):
    return (gcd(m, n) == 1) or (gcd(m, n) == 2)   # coprimality criterion
